    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Studies were included based on the following inclusion criteria: 1) studies involved sepsis patients; (2) observational studies; 3) studies that describe data about DIC diagnosis based on any of the three criteria (ISTH-DIC, JAAM-DIC, and SIC); 4) studies that reported the relationship between DIC diagnosis and at least one of the following outcomes: sensitivity or specificity or AUC to predict mortality.",
      "reason": "Population (sepsis patients), study design (observational), index test criteria, and outcome/reporting requirements are all specified."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "Studies were excluded if they were conference abstracts, case studies, reports of the same study, reviews...",
      "reason": "Publication status is addressed (conference abstracts, case reports, reviews excluded), but no language or dissemination year restrictions are reported."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_10",
      "quote": "studies which did not report sensitivity, specificity, or data to calculate the score performance characteristics",
      "reason": "The criteria do not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "Sixteen studies reported the performance of ISTH-DIC score involving 4466 patients; thirteen studies (3862 patients) reported the performance of JAAM-DIC score, and ten studies (4714 patients) reported the performance of SIC score.",
      "reason": "Synthesis groups by DIC score are evident (plus subgroup analysis by region and sepsis stage per text_4), but the grouping is not explicitly linked to the review objectives/comparisons in the eligibility criteria section."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_10",
      "quote": "Studies were excluded if they were conference abstracts, case studies, reports of the same study, reviews, studies which did not report sensitivity, specificity, or data to calculate the score performance characteristics.",
      "reason": "Restrictions are listed but no rationale is provided for any of them."
    }
